insert into audit_backup.rewrites_20261122_proposals (locale, slug, field, col, path, decision, old_text, new_text)
values
  ('fr', 'north-pindos-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'North Pindos National Park mesure 230 km de long et 70 km de large, fondé en [source datée] et est considéré comme l''une des zones les plus importantes au niveau national et européen. De plus, la variété des espèces rares doit être mentionnée car presque tous les grands mammifères de la Grèce continentale sont présents dans la zone. Un total de 60 espèces de mammifères, 166 espèces d''oiseaux, 30 espèces de reptiles, 14 espèces d''amphibiens et 17 espèces de poissons se trouvent dans le parc.', 'Le parc national du Pinde du Nord mesure 230 km de long sur 70 km de large et compte parmi les zones les plus importantes de Grèce et d''Europe. Presque tous les grands mammifères de la Grèce continentale y vivent : on y recense 60 espèces de mammifères, 166 d''oiseaux, 30 de reptiles, 14 d''amphibiens et 17 de poissons.'),
  ('fr', 'ostmarka-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Østmarka National Park est un parc national norvégien créé en [dated source]. Il couvre une superficie de 54 km2 à Østmarka, Oslo et dans les municipalités d''Akershus : Nordre Follo, Lørenskog, Røllen et Enebakk.', 'Le parc national d''Østmarka est un parc national norvégien qui couvre 54 km2 de la forêt d''Østmarka, à Oslo et dans les communes d''Akershus de Nordre Follo, Lørenskog, Rælingen et Enebakk.'),
  ('fr', 'paluma-range-national-park-qld', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'CLEAR', 'À l''occasion de la Journée des parcs nationaux [source datée], le gouvernement de l''État du Queensland a annoncé l''ajout de 6 510 hectares à Paluma Range National Park.', ''),
  ('fr', 'parc-naturel-regional-alpilles', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Alpilles Regional Nature Park est un parc naturel régional français créé en [dated source], en Provence-Alpes-Côte d''Azur dans le département des Bouches-du-Rhône. Il s''étend sur le massif calcaire préalpin des Alpilles et ses environs immédiats .', 'Le parc naturel régional des Alpilles se trouve dans les Bouches-du-Rhône, en Provence-Alpes-Côte d''Azur. Il s''étend sur le massif calcaire préalpin des Alpilles et ses abords immédiats.'),
  ('fr', 'parc-naturel-regional-aubrac', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Aubrac Regional Natural Park est un parc naturel régional français créé par décret le 23 mai [dated source], dont le périmètre occupe environ 2 282 km2 répartis sur 64 communes des trois départements de l''Aveyron, de la Lozère et du Cantal, autour du plateau du même nom. C''est le 53ème Parc Naturel Régional français.', 'Le parc naturel régional de l''Aubrac couvre environ 2 282 km2 répartis sur 64 communes de l''Aveyron, de la Lozère et du Cantal, autour du plateau de l''Aubrac. C''est le 53e parc naturel régional français.'),
  ('fr', 'parc-naturel-regional-de-guyane', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Parc naturel régional de Guyane est un parc naturel régional français créé en [dated source] en Guyane. Il est divisé en trois parties terrestres et deux portions maritimes, et couvre le territoire de six communes : Iracoubo, Mana, Ouanary, Roura, Saint-Georges et Sinnamary.', 'Le parc naturel régional de la Guyane se compose de trois parties terrestres et de deux parties maritimes. Il couvre le territoire de six communes : Iracoubo, Mana, Ouanary, Roura, Saint-Georges et Sinnamary.'),
  ('fr', 'parc-naturel-regional-des-baronnies-provencales', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le parc naturel régional des Baronnies provençales s''étend sur un massif alpin entre les départements de la Drôme et des Hautes-Alpes dans le sud-est de la France. Ce parc naturel régional a été créé le 26 janvier [dated source]. Il couvre 104 communes en tout ou en partie.', 'Le parc naturel régional des Baronnies provençales s''étend sur un massif alpin entre la Drôme et les Hautes-Alpes, dans le sud-est de la France. Il couvre tout ou partie de 104 communes.'),
  ('fr', 'parc-naturel-regional-des-baronnies-provencales', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Parc naturel régional des Baronnies provençales : Ce parc naturel régional a été créé le 26 janvier [dated source].', 'Parc naturel régional des Baronnies provençales : Un parc naturel régional sur un massif alpin entre la Drôme et les Hautes-Alpes, qui s''étend sur 104 communes.'),
  ('fr', 'parc-naturel-regional-des-baronnies-provencales', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Ce parc naturel régional a été créé le 26 janvier [dated source].', 'Un parc naturel régional sur un massif alpin entre la Drôme et les Hautes-Alpes, qui s''étend sur 104 communes.'),
  ('fr', 'parc-naturel-regional-des-prealpes-d-azur', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Parc naturel régional des Préalpes d''Azur est un parc naturel régional français créé le 30 mars [dated source] et situé dans le département des Alpes-Maritimes, en région Provence-Alpes-Côte d''Azur. Il est précisément situé dans les Préalpes de Grasse, entre les vallées de la Siagne, du Loup, de la Cagne, de l''Estéron et du Var.', 'Le parc naturel régional des Préalpes d''Azur se trouve dans les Alpes-Maritimes, en Provence-Alpes-Côte d''Azur. Il s''étend sur les Préalpes de Grasse, entre les vallées de la Siagne, du Loup, de la Cagne, de l''Estéron et du Var.'),
  ('fr', 'parc-naturel-regional-medoc', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Parc naturel régional du Médoc est un parc naturel régional situé dans le département de la Gironde, en région Nouvelle-Aquitaine, classé par décret du 24 mai [dated source]. Il devient le 54e parc naturel régional de France et couvre une partie de la région naturelle du Médoc.', 'Le parc naturel régional du Médoc se trouve en Gironde, dans la région Nouvelle-Aquitaine. C''est le 54e parc naturel régional de France ; il couvre une partie de la région naturelle du Médoc.'),
  ('fr', 'parc-naturel-regional-oisepays-de-france', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Parc naturel régional Oise-Pays de France, créé le 13 janvier [dated source] par décret du Premier ministre, s''étend sur 70 communes des départements de l''Oise et du Val-d''Oise. C''est l''un des rares parcs répartis sur deux régions administratives, le quatrième PNR des Hauts de France et le quatrième en Île-de-France.', 'Le parc naturel régional Oise-Pays de France couvre 70 communes de l''Oise et du Val-d''Oise. C''est l''un des rares parcs répartis sur deux régions : le quatrième PNR des Hauts-de-France et le quatrième d''Île-de-France.'),
  ('fr', 'parco-dei-monti-sicani', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le parc des Sicani Mountains était un parc naturel régional de Sicile établi le 19 décembre [dated source] et supprimé en juillet [dated source]. Il comprenait 12 municipalités dans les territoires du libre consortium municipal d''Agrigento et de la ville métropolitaine de Palermo, en Sicile.', 'Le parc des monts Sicani était un parc naturel régional de Sicile, supprimé depuis. Il comprenait 12 communes du libre consortium communal d''Agrigente et de la ville métropolitaine de Palerme.'),
  ('fr', 'parco-naturale-regionale-bosco-incoronata', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le parc naturel régional Bosco Incoronata est une zone naturelle protégée établie en [dated source] le long de la rivière Cervaro, à environ 12 kilomètres de la ville de Foggia, au cœur du Tavoliere des Pouilles.', 'Le parc naturel régional du Bosco Incoronata est une zone naturelle protégée le long du Cervaro, à une douzaine de kilomètres de Foggia, au cœur de la plaine du Tavoliere, dans les Pouilles.'),
  ('fr', 'parco-naturale-regionale-bosco-incoronata', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Parco naturale regionale Bosco Incoronata : Le parc naturel régional Bosco Incoronata est une zone naturelle protégée établie en [dated source] le long de la', 'Parco naturale regionale Bosco Incoronata : Une zone naturelle protégée le long du Cervaro, à une douzaine de kilomètres de Foggia, dans les Pouilles.'),
  ('fr', 'parco-naturale-regionale-bosco-incoronata', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Le parc naturel régional Bosco Incoronata est une zone naturelle protégée établie en [dated source] le long de la', 'Une zone naturelle protégée le long du Cervaro, à une douzaine de kilomètres de Foggia, dans les Pouilles.'),
  ('fr', 'parco-naturale-regionale-del-vulture', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le parc naturel régional du Vulture est une zone naturelle protégée créée en novembre [source datée]. Ce parc régional comprend la zone du Vulture ainsi qu''une partie des territoires communaux d''Atella, Barile, Ginestra, Melfi, Rapolla, Rionero in Vulture, Ripacandida, Ruvo del Monte et San Fele, appartenant tous à la province de Potenza.', 'Le parc naturel régional du Vulture est une zone naturelle protégée qui comprend le secteur du Vulture et une partie des communes d''Atella, Barile, Ginestra, Melfi, Rapolla, Rionero in Vulture, Ripacandida, Ruvo del Monte et San Fele, toutes situées dans la province de Potenza.'),
  ('fr', 'parco-naturale-regionale-del-vulture', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Parco naturale regionale del Vulture : Le parc naturel régional du Vulture est une zone naturelle protégée créée en novembre [source datée]. Ce parc rég', 'Parco naturale regionale del Vulture : Une zone naturelle protégée autour du Vulture, dont une partie de Melfi, dans la province de Potenza.'),
  ('fr', 'parco-naturale-regionale-del-vulture', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Le parc naturel régional du Vulture est une zone naturelle protégée créée en novembre [source datée]. Ce parc rég', 'Une zone naturelle protégée autour du Vulture, dont une partie de Melfi, dans la province de Potenza.'),
  ('fr', 'parco-naturale-regionale-litorale-di-ugento', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le parc régional Litorale di Ugento est une zone naturelle protégée des Pouilles établie par la loi régionale n° 13 du 28 mai [dated source]. Le parc est situé le long de la côte ionienne, dans la partie la plus méridionale de la péninsule du Salento, et est bordé par les villes de Torre San Giovanni et Lido Marini. Il protège, sur une profondeur d''environ trois kilomètres depuis la côte et sur une longueur de huit, une séquence côtière de grande valeur, composée d''un système dunaire et rétrodunaire, d''une série de bassins de marée et de canaux de liaison, d''un imposant récif fossile avec des gravine et de la zone la plus étendue de maquis méditerranéen du Salento.', 'Le parc régional du littoral d''Ugento est une zone naturelle protégée des Pouilles. Il longe la côte ionienne, à l''extrémité sud de la péninsule du Salento, entre Torre San Giovanni et Lido Marini. Sur environ trois kilomètres de profondeur et huit de longueur, il protège une séquence côtière très précieuse : un système de dunes et d''arrière-dunes, des bassins et des canaux de liaison, un imposant récif fossile et la plus vaste étendue de maquis méditerranéen du Salento.'),
  ('fr', 'parco-naturale-regionale-terra-delle-gravine', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le parc naturel Terra delle Gravine est une zone naturelle protégée établie dans les Pouilles en [dated source]. La zone couvre les provinces de Brindisi et de Tarente, dans la région des Murge.', 'Le parc naturel de la Terra delle Gravine est une zone naturelle protégée des Pouilles, qui s''étend sur une partie des provinces de Brindisi et de Tarente, dans les Murges.'),
  ('fr', 'ponga-nature-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le parc naturel de Ponta est un espace naturel protégé espagnol, situé dans la zone centrale de la chaîne Cantábrica avec une zone protégée de 20 533 ha, dont la majeure partie constitue le conseil municipal de Ponta. Il était initialement prévu d''être inclus dans le Reds Park à la fin de la période et son nom en tant que parc naturel est venu plus tard avec sa propre identité. Il a été déclaré par la loi 4 / [dated source].', 'Le parc naturel de Ponga est un espace naturel protégé espagnol au centre de la cordillère Cantabrique, d''une superficie protégée de 20 533 ha, situé en majeure partie sur la commune de Ponga.'),
  ('fr', 'reinheimen-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Reinheimen National Park est un parc national en Norvège qui a été établi en [dated source]. Le parc se compose d''une zone montagneuse protégée continue de 1 969 kilomètres carrés. Il est situé dans les comtés de Møre og Romsdal et d''Innlandet en Norvège. Le parc comprend des parties des municipalités de Lesja, Skjåk, Vågå, Lom, Fjord et Rauma. Le parc se compose d''une grande partie de la chaîne de montagnes Tafjordfjella ainsi que de l''habitat des rennes dans la partie nord de la vallée d''Ottadalen.', 'Le parc national de Reinheimen est un parc national norvégien qui protège un massif montagneux d''un seul tenant de 1 969 kilomètres carrés dans les comtés de Møre og Romsdal et d''Innlandet. Il comprend une partie des communes de Lesja, Skjåk, Vågå, Lom, Fjord et Rauma, une grande partie du massif du Tafjordfjella et l''habitat des rennes au nord de la vallée d''Ottadalen.'),
  ('fr', 'reynisdrangar', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Reynisdrangar : Dans [dated source], Reynisfjara [ˈreiːnɪsˌfjaːra] a été classée sixième meilleure plage au monde.', 'Reynisdrangar : Des aiguilles de basalte au pied du Reynisfjall, près de Vík í Mýrdal, bordées par une plage de sable noir.'),
  ('fr', 'reynisdrangar', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Dans [dated source], Reynisfjara [ˈreiːnɪsˌfjaːra] a été classée sixième meilleure plage au monde.', 'Des aiguilles de basalte au pied du Reynisfjall, près de Vík í Mýrdal, bordées par une plage de sable noir.'),
  ('fr', 'reynisfjara', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Reynisfjara est une plage de sable noir populaire dans le sud de l''Islande, près de la ville de Vík í Mýrdal. Elle fait partie du Katla UNESCO Global Geopark sur un terrain privé. En février [dated source], après des semaines de fortes vagues et de vents d''est, une partie des colonnes de basalte emblématiques s''est effondrée en même temps qu''une érosion importante de la plage. Avec le retour des vents d''ouest en mars, Reynisfjara devrait retrouver son apparence familière.', 'Reynisfjara est une plage de sable noir très fréquentée du sud de l''Islande, près de la ville de Vík í Mýrdal. Elle fait partie du géoparc mondial UNESCO de Katla et se trouve sur un terrain privé.'),
  ('fr', 'rhine-falls', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Rhine Falls : Du 13 novembre [dated source] au 3 janvier [dated source] : L''illumination du Schloss Laufen sur le Rhine Fa', 'Rhine Falls : La plus grande chute d''eau d''Europe, entre les châteaux de Laufen et de Wörth, visible depuis le pont des CFF.'),
  ('fr', 'rhine-falls', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Du 13 novembre [dated source] au 3 janvier [dated source] : L''illumination du Schloss Laufen sur le Rhine Fa', 'La plus grande chute d''eau d''Europe, entre les châteaux de Laufen et de Wörth, visible depuis le pont des CFF.'),
  ('fr', 'rohkunborri-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Rohkunborri National Park est un parc national du comté de Troms, en Norvège, qui a été établi en [dated source]. Le parc consiste en une zone protégée de 571 kilomètres carrés et est situé dans la municipalité de Bardu, le long de la frontière avec la Suède, à environ 30 kilomètres au sud-est du village de Setermoen et à environ 50 kilomètres au nord-est de la ville de Narvik.', 'Le parc national de Rohkunborri se trouve dans le comté de Troms, en Norvège, et protège 571 kilomètres carrés. Il s''étend dans la commune de Bardu, le long de la frontière suédoise, à environ 30 kilomètres au sud-est du village de Setermoen et à une cinquantaine de kilomètres au nord-est de la ville de Narvik.'),
  ('fr', 'rosalia-kogelberg-nature-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Dans le cadre du projet « Expérience de la nature sans barrières Rosalia-Kogelberg », une expérience de randonnée et de nature pour tous les sens a été créée entre [dated source] et [dated source]. Le projet comprenait, entre autres, la conception et la construction d''un total de onze stations d''expérience et de repos sans barrières le long de ce qu''on appelle l''Eulenweg ou le long du « Tour Teichwiesen ».', 'Dans le cadre du projet « Nature sans obstacles Rosalia-Kogelberg », un parcours de randonnée et de découverte de la nature pour tous les sens a été aménagé. Le projet a notamment permis de concevoir et de construire onze stations de découverte et de repos accessibles le long de l''Eulenweg et du « Tour Teichwiesen ».'),
  ('fr', 'saimaa-unesco-global-geopark', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Saimaa UNESCO Global Geopark : La zone a reçu le statut de UNESCO Global Geopark en [dated source].', 'Saimaa UNESCO Global Geopark : Un géoparc mondial UNESCO de 65 géosites autour du lac Saimaa, le plus grand lac de Finlande.'),
  ('fr', 'saimaa-unesco-global-geopark', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'La zone a reçu le statut de UNESCO Global Geopark en [dated source].', 'Un géoparc mondial UNESCO de 65 géosites autour du lac Saimaa, le plus grand lac de Finlande.'),
  ('fr', 'sainte-baume-regional-nature-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Sainte-Baume Regional Nature Park est un parc naturel régional créé par décret le 20 décembre [dated source], avec un périmètre d''environ 84 367 ha répartis entre les deux départements des Bouches-du-Rhône et du Var, autour du massif du même nom. C''est le 52ème parc naturel régional français.', 'Le parc naturel régional de la Sainte-Baume couvre environ 84 367 ha répartis entre les Bouches-du-Rhône et le Var, autour du massif du même nom. C''est le 52e parc naturel régional français.'),
  ('fr', 'salpausselka-unesco-global-geopark', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Salpausselkä UNESCO Global Geopark : Salpausselkä Geopark a été accepté le 13 avril [source datée].', 'Salpausselkä UNESCO Global Geopark : Le géoparc de Salpausselkä s''étend sur Lahti, Hollola, Asikkala, Heinola, Sysma et Padasjoki, en Finlande.'),
  ('fr', 'salpausselka-unesco-global-geopark', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Salpausselkä Geopark a été accepté le 13 avril [source datée].', 'Le géoparc de Salpausselkä s''étend sur Lahti, Hollola, Asikkala, Heinola, Sysma et Padasjoki, en Finlande.'),
  ('fr', 'salzburger-lungau-and-karntner-nockberge-biosphere', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Salzburger Lungau et les Carinthian Nockberge adjacents ont été classés Réserve de biosphère par l''UNESCO en juillet [source datée]. Elle couvre l''ensemble du district salzbourgeois de Tamsweg (Lungau) et les zones adjacentes des Nockberge en Carinthie. Cela fait de cette zone bordant les États fédéraux de Salzbourg et de Carinthie une « région modèle pour le développement durable ».', 'Le Lungau salzbourgeois et les Nockberge carinthiens voisins sont reconnus par l''UNESCO comme parc de biosphère. Celui-ci couvre tout le district salzbourgeois de Tamsweg (Lungau) et les zones voisines des Nockberge, en Carinthie, ce qui fait de cette région frontalière une « région modèle pour le développement durable ».'),
  ('fr', 'sequoia-park-of-monte-cabezon', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Les éléments suivants sont un « espace naturel protégé » de Cantabrie, déclaré Monument Naturel par le Décret 41 / [dated source] du Gouvernement de Cantabrie et inclus dans le Réseau des Espaces Naturels Protégés par la Loi de Cantabrie 4 / [dated source] du 19 mai.', 'Le parc des séquoias du mont Cabezón est un espace naturel protégé de Cantabrie, déclaré monument naturel par le gouvernement de Cantabrie et intégré au réseau des espaces naturels protégés de la région.'),
  ('fr', 'sequoia-park-of-monte-cabezon', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Sequoia Park of Monte Cabezón : Les éléments suivants sont un « espace naturel protégé » de Cantabrie, déclaré Monument naturel par le décret 41 / [dated ', 'Sequoia Park of Monte Cabezón : Le parc des séquoias du mont Cabezón est un monument naturel et un espace naturel protégé de Cantabrie.'),
  ('fr', 'sequoia-park-of-monte-cabezon', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Les éléments suivants sont un « espace naturel protégé » de Cantabrie, déclaré Monument naturel par le décret 41 / [dated ', 'Le parc des séquoias du mont Cabezón est un monument naturel et un espace naturel protégé de Cantabrie.'),
  ('fr', 'serra-da-encina-da-lastra-natural-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Sierra de la Lasse Natural Park () () () () est un espace naturel protégé espagnol situé dans le nord-est de la province d''Orense, dans la municipalité de Rubiana, Valdeoras, et a été déclaré Parc Naturel en [dated source] par le Conseil de Galice. Il a une superficie de 3151.67 ha et une altitude moyenne de 684 m. C''est une vallée calcaire aux pentes prononcées et aux falaises avec une forêt méditerranéenne. Une zone d''intérêt public particulièrement importante, notamment pour ses populations de rapaces, parmi lesquelles la présence de l''Aigle royal et du Faucon pèlerin. L''abondance de grottes - appelées ici des pelles - conduit à l''existence de nombreuses colonies de chauves-souris, les plus importantes de Galice. Un autre point d''intérêt réside dans la présence de zones de pâturage de type méditerranéen caractéristiques des zones de montagnes rocheuses.)', 'Le parc naturel de la Serra da Enciña da Lastra est un espace naturel protégé espagnol situé au nord-est de la province d''Ourense, dans la commune de Rubiá (Valdeoras), et déclaré parc naturel par le gouvernement de Galice. Il couvre 3 151,67 ha pour une altitude moyenne de 684 m : une vallée calcaire aux pentes raides et aux falaises, couverte de forêt méditerranéenne. Il est particulièrement important pour les rapaces, dont l''aigle royal et le faucon pèlerin. Ses nombreuses grottes abritent d''importantes colonies de chauves-souris, les plus importantes de Galice, et l''on y trouve aussi des pâturages de type méditerranéen propres aux montagnes rocheuses.'),
  ('fr', 'serra-de-tramuntana', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'La Serra de Tramuntana (en catalan baléare : [ˈsɛrə ðə tɾəmunˈtanə]) est une chaîne de montagnes orientée sud-ouest-nord-est qui forme l''épine dorsale septentrionale de l''île espagnole de Majorque. C''est également le nom donné à la comarca de la même zone. Le 27 juin [dated source], la Tramuntana Range a été inscrite au patrimoine mondial de l''UNESCO en tant que zone d''une grande importance physique et culturelle.', 'La Serra de Tramuntana est une chaîne de montagnes orientée sud-ouest–nord-est qui forme l''épine dorsale nord de l''île de Majorque ; c''est aussi le nom de la comarque correspondante. La Serra de Tramuntana est inscrite au patrimoine mondial de l''UNESCO pour sa grande valeur physique et culturelle.'),
  ('fr', 'sila-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Sila National Park (italien : Parco nazionale della Sila) est un parc national italien en Calabre, situé sur le plateau de la Sila. Établi en 1997, il couvre environ 74 000 hectares (180 000 acres). Ses sommets les plus élevés sont le Mt. Botte Donato (1 928 m), dans la Sila Grande, et le Mt. Gariglione (1 764 m) dans la Sila Piccola. Le parc a été créé par le décret régional du 14 novembre [source datée] et comprend son propre organisme de gestion. Le parc inclut les territoires faisant autrefois partie du Calabria National Park (1968) et protège des zones de grand intérêt environnemental dans la Sila Piccola, la Sila Grande et la Sila Greca, pour un total de 736,95 kilomètres carrés (284,54 sq mi), répartis sur 21 municipalités (comuni) et 6 « communautés de montagne » (comunità montane) à travers les trois provinces calabraises de Catanzaro, Cosenza et Crotone.', 'Le parc national de la Sila (en italien : Parco nazionale della Sila) se trouve en Calabre, sur le plateau de la Sila. Créé en 1997, il couvre environ 74 000 hectares. Ses plus hauts sommets sont le mont Botte Donato (1 928 m), dans la Sila Grande, et le mont Gariglione (1 764 m), dans la Sila Piccola. Le parc reprend des territoires de l''ancien parc national de Calabre (1968) et protège des zones de grand intérêt environnemental dans la Sila Piccola, la Sila Grande et la Sila Greca, sur 21 communes des provinces de Catanzaro, Cosenza et Crotone.'),
  ('fr', 'sjunkhatten-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Sjunkhatten National Park a été établi en [dated source] dans le comté de Nordland, en Norvège. Le parc consiste en une zone protégée continue de 417,5 kilomètres carrés, incluant une zone maritime de 39,8 kilomètres carrés dans les municipalités de Bodø, Fauske et Sørfold. Le parc est situé sur une péninsule entre le fjord Sørfolda et le Saltfjorden, comprenant un paysage formé par les glaciers, des grottes et des réseaux hydrographiques, des fjords, le grand lac Heggmovatnet, des espèces animales rares et un patrimoine culturel.', 'Le parc national de Sjunkhatten se trouve dans le comté de Nordland, en Norvège. Il forme une zone protégée d''un seul tenant de 417,5 kilomètres carrés, dont 39,8 kilomètres carrés de mer, sur les communes de Bodø, Fauske et Sørfold. Le parc occupe une péninsule entre le fjord de Sørfolda et le Saltfjorden, avec des paysages glaciaires, des grottes et des réseaux hydrographiques, des fjords, le grand lac Heggmovatnet, des espèces animales rares et un patrimoine culturel.'),
  ('fr', 'sjunkhatten-national-park', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Sjunkhatten National Park : Sjunkhatten National Park a été établi en [dated source] dans le comté de Nordland, en Norvège.', 'Sjunkhatten National Park : Un parc national de 417,5 km2 sur une péninsule entre le Sørfolda et le Saltfjorden, dans le Nordland.'),
  ('fr', 'sjunkhatten-national-park', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'Sjunkhatten National Park a été établi en [dated source] dans le comté de Nordland, en Norvège.', 'Un parc national de 417,5 km2 sur une péninsule entre le Sørfolda et le Saltfjorden, dans le Nordland.'),
  ('fr', 'south-harz-nature-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le South Harz Nature Park (allemand : Naturpark Südharz) est situé dans le district de Nordhausen, dans le nord de la Thuringe, en Allemagne. L''acte désignant ce parc naturel dans les montagnes du Harz est entré en vigueur le 31 décembre [source datée] et a ainsi fondé le cinquième parc naturel de Thuringe. Il a une superficie de 267 km². Le parc est géré par l''Association touristique du Sud-Harz (Südharzer Tourismusverband e.V.) conjointement avec le parc naturel de Kyffhäuser.', 'Le parc naturel du Harz méridional (en allemand : Naturpark Südharz) se trouve dans l''arrondissement de Nordhausen, au nord de la Thuringe, en Allemagne. C''est le cinquième parc naturel de Thuringe ; il couvre 267 km² du massif du Harz. Il est géré par l''office de tourisme du Harz méridional (Südharzer Tourismusverband e.V.) en lien avec le parc naturel du Kyffhäuser.'),
  ('fr', 'southern-black-forest-biosphere-area', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'La réserve de biosphère de la Forêt-Noire est située dans le sud de la Forêt-Noire et a été créée en [dated source]. Le bureau est situé dans la ville de Schönau en Forêt-Noire. Après la réserve de biosphère de la Schwäbische Alb créée en [dated source], il s''agit de la deuxième réserve de biosphère du Bade-Wurtemberg. À la mi-juin [dated source], elle a été reconnue par l''UNESCO comme « réserve de biosphère de l''UNESCO ».', 'La réserve de biosphère de la Forêt-Noire se trouve dans le sud de la Forêt-Noire ; son bureau est installé à Schönau im Schwarzwald. Après celle du Jura souabe, c''est la deuxième réserve de biosphère du Bade-Wurtemberg, et l''UNESCO l''a reconnue comme réserve de biosphère.'),
  ('fr', 'southern-black-forest-biosphere-area', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Southern Black Forest Biosphere Area : La réserve de biosphère de la Forêt-Noire est située dans le sud de la Forêt-Noire et a été créée en [dated source].', 'Southern Black Forest Biosphere Area : Une réserve de biosphère UNESCO dans le sud de la Forêt-Noire, dont le bureau se trouve à Schönau.'),
  ('fr', 'southern-black-forest-biosphere-area', 'tagline', 'fields', '{tagline}'::text[], 'REWRITE', 'La réserve de biosphère de la Forêt-Noire est située dans le sud de la Forêt-Noire et a été créée en [dated source].', 'Une réserve de biosphère UNESCO dans le sud de la Forêt-Noire, dont le bureau se trouve à Schönau.'),
  ('fr', 'sparbach-nature-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'CLEAR', 'Pendant le confinement d''avril [source datée], un pin noir a été « gemmé » dans le Naturpark Sparbach. Cet événement a été immortalisé dans un film.', ''),
  ('fr', 'sparbach-nature-park', 'metaDescription', 'fields', '{metaDescription}'::text[], 'CLEAR', 'Sparbach Nature Park : Während des Lockdown im April [dated source] wurde im Naturpark Sparbach eine Schwarzföhre „angepecht“. Dieses', ''),
  ('fr', 'sparbach-nature-park', 'tagline', 'fields', '{tagline}'::text[], 'CLEAR', 'Während des Lockdown im April [dated source] wurde im Naturpark Sparbach eine Schwarzföhre „angepecht“. Dieses', ''),
  ('fr', 'tomorr-mountain-national-park', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Tomorr Mountain National Park est un parc national fondé en 1956 qui se situe dans le sud de l''Albanie, niché dans les parties centrales et supérieures du massif du Tomorr, s''étendant sur une superficie de 261.06 km2 depuis [dated source], et agrandi pour inclure ses zones de carrières depuis [dated source]. Le parc couvre un territoire de 26,106 ha . La zone relève du comté de Berat et seulement 1,278 ha à l''intérieur du comté d''Elbasan. Le parc a été créé en 1956 et est considéré comme l''une des zones protégées les plus importantes pour le maintien de la biodiversité montagneuse et de l''intégrité de l''écosystème au niveau national. Le parc a été reconnu comme une Important Plant Area d''importance internationale par Plantlife.', 'Le parc national du mont Tomorr, fondé en 1956, se trouve dans le sud de l''Albanie, sur les parties centrales et élevées du massif du Tomorr, et couvre 261,06 km2 (26 106 ha). Il s''étend surtout dans le comté de Berat, avec seulement 1 278 ha dans celui d''Elbasan. Il compte parmi les aires protégées les plus importantes du pays pour la biodiversité et l''intégrité des écosystèmes de montagne, et Plantlife l''a reconnu comme zone importante pour les plantes d''intérêt international.'),
  ('fr', 'tongariro-northern-circuit', 'days[0].stops[0].detail', 'fields', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Le Tongariro Northern Circuit, l''une des Great Walks de Nouvelle-Zélande, propose une randonnée de trois à quatre jours à travers le Tongariro National Park New Zealand. Marqué par la Tongariro Alpine Crossing, une journée complète de paysages grandioses, l''ensemble du sentier s''étend sur 50 kilomètres autour du Mount Ngauruhoe. Environ 2 500 randonneurs ont terminé la marche au cours de la saison [dated source]/22. Cela contraste avec les quelque 25 000 personnes qui parcourent uniquement le segment Tongariro Crossing.', 'Le Tongariro Northern Circuit, l''une des Great Walks de Nouvelle-Zélande, est une randonnée de trois à quatre jours dans le parc national de Tongariro. Point fort du parcours, la Tongariro Alpine Crossing offre une journée entière de paysages saisissants ; l''ensemble du sentier fait environ 50 kilomètres autour du mont Ngauruhoe.'),
  ('fr', 'tongariro-northern-circuit', 'metaDescription', 'fields', '{metaDescription}'::text[], 'REWRITE', 'Tongariro Northern Circuit : Environ 2 500 randonneurs ont terminé la marche au cours de la saison [dated source]/22.', 'Tongariro Northern Circuit : Une Great Walk de trois à quatre jours dans le parc national de Tongariro, autour du mont Ngauruhoe (50 km).')
